   528	func (ng *nodegroup) IsMachineDeploymentAndRollingOut() (bool, error) {
   529		if ng.scalableResource.Kind() != machineDeploymentKind {
   530			// Not a MachineDeployment.
   531			return false, nil
   532		}
   533	
   534		machineSets, err := ng.machineController.listMachineSetsForMachineDeployment(ng.scalableResource.unstructured)
   535		if err != nil {
   536			return false, err
   537		}
   538	
   539		if len(machineSets) == 0 {
   540			// No MachineSets => MD is not rolling out.
   541			return false, nil
   542		}
   543	
   544		// Find the latest revision, the MachineSet with the latest revision is the MachineSet that
   545		// matches the MachineDeployment spec.
   546		var latestMSRevisionInt int64
   547		for _, ms := range machineSets {
   548			msRevision, ok := ms.GetAnnotations()[machineDeploymentRevisionAnnotation]
   549			if !ok {
   550				continue
   551			}
   552	
   553			msRevisionInt, err := strconv.ParseInt(msRevision, 10, 64)
   554			if err != nil {
   555				return false, errors.Wrapf(err, "failed to parse current revision on MachineSet %s", klog.KObj(ms))
   556			}
   557			latestMSRevisionInt = max(latestMSRevisionInt, msRevisionInt)
   558		}
   559		maxMSRevision := strconv.FormatInt(latestMSRevisionInt, 10)
   560	
   561		for _, ms := range machineSets {
   562			if ms.GetAnnotations()[machineDeploymentRevisionAnnotation] == maxMSRevision {
   563				// Ignore the MachineSet with the latest revision
   564				continue
   565			}
   566	
   567			// Check if any of the old MachineSets still have replicas
   568			replicas, found, err := unstructured.NestedInt64(ms.UnstructuredContent(), "spec", "replicas")
   569			if err != nil {
   570				return false, errors.Wrapf(err, "failed to find spec replicas on MachineSet %s", klog.KObj(ms))
   571			}
   572			if found && replicas > 0 {
   573				// Found old MachineSets that still has replicas => MD is still rolling out.
   574				return true, nil
   575			}
   576			replicas, found, err = unstructured.NestedInt64(ms.UnstructuredContent(), "status", "replicas")
   577			if err != nil {
