382	// TemplateNodeInfo returns a schedulercache.NodeInfo structure of an
383	// empty (as if just started) node. This will be used in scale-up
384	// simulations to predict what would a new node look like if a node
385	// group was expanded. The returned NodeInfo is expected to have a
386	// fully populated Node object, with all of the labels, capacity and
387	// allocatable information as well as all pods that are started on the
388	// node by default, using manifest (most likely only kube-proxy).
389	// Implementation optional.
390	func (ng *nodegroup) TemplateNodeInfo(ctx context.Context) (*framework.NodeInfo, error) {
391		if !ng.scalableResource.CanScaleFromZero() {
392			return nil, cloudprovider.ErrNotImplemented
393		}
394	
395		capacity, err := ng.scalableResource.InstanceCapacity()
396		if err != nil {
397			return nil, err
398		}
399	
400		nodeName := fmt.Sprintf("%s-asg-%d", ng.scalableResource.Name(), rand.Int63())
401		node := corev1.Node{
402			ObjectMeta: metav1.ObjectMeta{
403				Name:   nodeName,
404				Labels: map[string]string{},
405			},
406		}
407	
408		nsi := ng.scalableResource.InstanceSystemInfo()
409		if nsi != nil {
410			node.Status.NodeInfo = *nsi
411		}
412	
413		node.Status.Capacity = capacity
414		node.Status.Allocatable = capacity
415		node.Status.Conditions = cloudprovider.BuildReadyConditions()
416		node.Spec.Taints = ng.scalableResource.Taints()
417	
418		node.Labels, err = ng.buildTemplateLabels(nodeName, nsi)
419		if err != nil {
420			return nil, err
421		}
422	
423		resourceSlices, err := ng.scalableResource.InstanceResourceSlices(nodeName)
424		if err != nil {
425			return nil, err
426		}
427		csiNode := ng.scalableResource.InstanceCSINode()
428	
429		nodeInfo := framework.NewNodeInfo(&node, resourceSlices, framework.NewPodInfo(cloudprovider.BuildKubeProxy(ng.scalableResource.Name()), nil))
430		if csiNode != nil {
431			nodeInfo.SetCSINode(csiNode)
432		}
433		return nodeInfo, nil
434	}
