436	func (ng *nodegroup) buildTemplateLabels(nodeName string, nsi *corev1.NodeSystemInfo) (map[string]string, error) {
437		nsiLabels := make(map[string]string)
438		if nsi != nil {
439			nsiLabels[corev1.LabelArchStable] = nsi.Architecture
440			nsiLabels[corev1.LabelOSStable] = nsi.OperatingSystem
441		}
442	
443		// The order of priority is:
444		// - Labels set in existing nodes for not-autoscale-from-zero cases
445		// - Labels set in the labels capacity annotation of machine template, machine set, and machine deployment.
446		// - Values in the status.nodeSystemInfo of MachineTemplates
447		// - Generic/default labels set in the environment of the cluster autoscaler
448		labels := cloudprovider.JoinStringMaps(buildGenericLabels(nodeName), nsiLabels, ng.scalableResource.Labels())
449	
450		nodes, err := ng.Nodes(context.TODO())
451		if err != nil {
452			return nil, err
453		}
454	
455		if len(nodes) > 0 {
456			node, err := ng.machineController.findNodeByProviderID(normalizedProviderString(nodes[0].Id))
457			if err != nil {
458				return nil, err
459			}
460	
461			if node != nil {
462				labels = cloudprovider.JoinStringMaps(labels, extractNodeLabels(node))
463			}
464		}
465		return labels, nil
466	}
